mapper.update:
update book
set visit_count = visit_count + #{visitCount}
where id = #{bookId}

mapper.select:
select b.id, b.cat_id, b.cat_name, b.book_name, b.author_id, b.author_name, b.pic_url, b.book_desc, b.score, b.book_status, b.visit_count, b.word_count, b.comment_count, b.last_index_id, b.last_index_name, b.last_index_update_time, b.is_vip, b.status, b.age_rating, b.audit_status, b.cover_audit_status from book b
left join ( select weighted.cat_id, sum(weighted.signal_weight) as affinity_score from ( select shelf_book.cat_id, 5 as signal_weight from user_bookshelf shelf inner join book shelf_book on shelf.book_id = shelf_book.id where shelf.user_id = #{userId} union all select history_book.cat_id, 3 as signal_weight from user_read_history history inner join book history_book on history.book_id = history_book.id where history.user_id = #{userId} union all select purchase_book.cat_id, 8 as signal_weight from ( select distinct book_id from user_buy_record where user_id = #{userId} and book_id is not null ) purchase inner join book purchase_book on purchase.book_id = purchase_book.id ) weighted group by weighted.cat_id ) affinity on affinity.cat_id = b.cat_id
where b.status = 1 and b.word_count > 0 and b.last_index_id is not null and b.audit_status = 1 and b.cover_audit_status = 1 and coalesce(b.age_rating, 0) <= #{maxAgeRating}
and b.id != #{excludedBookId}
and not exists ( select 1 from user_bookshelf known_shelf where known_shelf.user_id = #{userId} and known_shelf.book_id = b.id ) and not exists ( select 1 from user_read_history known_history where known_history.user_id = #{userId} and known_history.book_id = b.id ) and not exists ( select 1 from user_buy_record known_purchase where known_purchase.user_id = #{userId} and known_purchase.book_id = b.id )
order by
coalesce(affinity.affinity_score, 0) + case when b.cat_id = #{preferredCatId} then 4 else 0 end desc,
coalesce(affinity.affinity_score, 0) desc,
case when b.cat_id = #{preferredCatId} then 4 else 0 end desc,
coalesce(b.score, 0) desc, coalesce(b.visit_count, 0) desc, coalesce(b.comment_count, 0) desc, b.last_index_update_time desc, b.id desc limit #{limit}

mapper.update:
update book
set comment_count = comment_count + 1
where id = #{bookId}
